// Procedural placeholder art — zero art files; every function returns an HTMLCanvasElement at native pixel size.

// --- Inlined canvas helpers (from raster's canvas-util.ts) — DOM is only touched when called. ---

/**
 * Maximum safe canvas dimension in pixels. Every canvas this module creates is
 * clamped to `[1, MAX_CANVAS_DIM]` to avoid a 0/NaN throw on some browsers and
 * an OOM on iOS Safari (which caps at ~4096²).
 */
const MAX_CANVAS_DIM = 4096;

/**
 * Clamp `n` to a safe canvas dimension: a finite integer in `[1, MAX_CANVAS_DIM]`.
 * Non-finite input (NaN / Infinity) collapses to 1.
 */
function clampCanvasDim(n: number): number {
  if (!Number.isFinite(n)) return 1;
  return Math.min(MAX_CANVAS_DIM, Math.max(1, Math.floor(n)));
}

/**
 * Create and return a new `HTMLCanvasElement` sized to clamped `[1, MAX_CANVAS_DIM]`
 * dimensions. Touches the DOM at call time.
 */
function createCanvas(width: number, height: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = clampCanvasDim(width);
  canvas.height = clampCanvasDim(height);
  return canvas;
}

function makeCanvas(w: number, h: number): { canvas: HTMLCanvasElement; ctx: CanvasRenderingContext2D } {
  const canvas = createCanvas(w, h);
  const ctx = canvas.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  return { canvas, ctx };
}

// ---------------------------------------------------------------------------
// Environment maps (chrome-ball sphere maps)
// ---------------------------------------------------------------------------

/** Options for {@link envMap}. */
export interface EnvMapOptions {
  /** Canvas edge length in pixels (square). Default `64`. */
  size?: number;
  /** Sky colour at the top of the reflection. Default `'#7ec8ff'`. */
  sky?: string;
  /** Horizon band colour. Default `'#f5e9d0'`. */
  horizon?: string;
  /** Ground colour at the bottom. Default `'#4a3b2a'`. */
  ground?: string;
  /** Sun / key-light hotspot colour. `null` removes it. Default `'#ffffff'`. */
  sun?: string | null;
  /** Integer seed for the horizontal cloud/highlight streaks. Default `7`. */
  seed?: number;
}

/**
 * A spherical environment map — "the world reflected in a chrome ball" — for
 * fake-reflection sphere mapping on 3D materials (use the canvas as a texture,
 * e.g. register it with `game.assets.frames(...)`). Sky above,
 * ground below, a bright sun hotspot and horizontal streaks: the streaks are
 * what sells the fake chrome when it sweeps across a surface. Colour the world
 * to match your scene (night: dark sky, fire-orange sun).
 */
export function envMap(opts: EnvMapOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 64;
  const sky = opts.sky ?? '#7ec8ff';
  const horizon = opts.horizon ?? '#f5e9d0';
  const ground = opts.ground ?? '#4a3b2a';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.imageSmoothingEnabled = true; // smooth gradients, not pixel art

  const g = ctx.createLinearGradient(0, 0, 0, s);
  g.addColorStop(0, sky);
  g.addColorStop(0.42, sky);
  g.addColorStop(0.5, horizon);
  g.addColorStop(0.58, horizon);
  g.addColorStop(0.7, ground);
  g.addColorStop(1, ground);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);

  // Horizontal streaks above and below the horizon — the classic chrome bands.
  const rand = rng(opts.seed ?? 7);
  for (let i = 0; i < 6; i++) {
    const above = i % 2 === 0;
    const y = above ? s * (0.12 + rand() * 0.28) : s * (0.62 + rand() * 0.3);
    const h = s * (0.015 + rand() * 0.035);
    ctx.fillStyle = above ? 'rgba(255,255,255,0.35)' : 'rgba(0,0,0,0.25)';
    ctx.fillRect(0, y, s, Math.max(1, h));
  }

  if (opts.sun !== null) {
    const sg = ctx.createRadialGradient(s * 0.68, s * 0.22, 0, s * 0.68, s * 0.22, s * 0.2);
    sg.addColorStop(0, opts.sun ?? '#ffffff');
    sg.addColorStop(0.35, 'rgba(255,255,255,0.55)');
    sg.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sg;
    ctx.fillRect(0, 0, s, s);
  }
  return canvas;
}

// Deterministic PRNG; a given seed always yields the same pixel pattern.
function rng(seed: number): () => number {
  let s = (seed | 0) || 1;
  return () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
}

// ---------------------------------------------------------------------------
// Normal maps (tangent-space, for lit 3D materials)
// ---------------------------------------------------------------------------

/** Options for {@link noiseNormalMap} and {@link brickNormalMap}. */
export interface NormalMapOptions {
  /** Canvas edge length in pixels (square). Default `64`. */
  size?: number;
  /** Bump frequency for the noise map — lattice cells per tile edge. Default `5`. */
  scale?: number;
  /** Relief strength — slope steepness. `1` reads clearly; `2` is heavy relief. Default `1`. */
  strength?: number;
  /** Integer seed for deterministic patterns. Default `7`. */
  seed?: number;
}

// Convert a wrap-tiling height field (values ~0..1, size×size) into a
// tangent-space normal-map canvas via central differences. `amp` scales the
// height into pixel units, so slope steepness is resolution-independent. @internal
function heightFieldToNormalMap(h: Float32Array, size: number, amp: number): HTMLCanvasElement {
  const { canvas, ctx } = makeCanvas(size, size);
  const img = ctx.createImageData(size, size);
  const d = img.data;
  for (let y = 0; y < size; y++) {
    const ym = ((y - 1 + size) % size) * size;
    const yp = ((y + 1) % size) * size;
    const yr = y * size;
    for (let x = 0; x < size; x++) {
      const xm = (x - 1 + size) % size;
      const xp = (x + 1) % size;
      const dx = (h[yr + xp] - h[yr + xm]) * 0.5 * amp;
      const dy = (h[yp + x] - h[ym + x]) * 0.5 * amp;
      const inv = 1 / Math.hypot(dx, dy, 1);
      const i = (yr + x) * 4;
      d[i] = Math.round((-dx * inv * 0.5 + 0.5) * 255);
      d[i + 1] = Math.round((-dy * inv * 0.5 + 0.5) * 255);
      d[i + 2] = Math.round((inv * 0.5 + 0.5) * 255);
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return canvas;
}

// Tileable value noise: a wrapped random lattice of `cells²` values sampled
// with smoothstep-bilinear interpolation. @internal
function noiseField(size: number, cells: number, rand: () => number): Float32Array {
  const g = new Float32Array(cells * cells);
  for (let i = 0; i < g.length; i++) g[i] = rand();
  const out = new Float32Array(size * size);
  for (let y = 0; y < size; y++) {
    const fy = (y / size) * cells;
    const cy = Math.floor(fy);
    const ty = fy - cy;
    const sy = ty * ty * (3 - 2 * ty);
    const y0 = (cy % cells) * cells;
    const y1 = ((cy + 1) % cells) * cells;
    for (let x = 0; x < size; x++) {
      const fx = (x / size) * cells;
      const cx = Math.floor(fx);
      const tx = fx - cx;
      const sx = tx * tx * (3 - 2 * tx);
      const x0 = cx % cells;
      const x1 = (cx + 1) % cells;
      const top = g[y0 + x0] + (g[y0 + x1] - g[y0 + x0]) * sx;
      const bot = g[y1 + x0] + (g[y1 + x1] - g[y1 + x0]) * sx;
      out[y * size + x] = top + (bot - top) * sy;
    }
  }
  return out;
}

/**
 * A tileable NOISE normal map — bumpy stone, hammered metal, rough plaster —
 * for use as a tangent-space normal-map texture on lit 3D materials.
 * Two octaves of wrapped value noise turned into surface slopes: the lighting
 * picks out per-pixel bumps that flat geometry can't show. `scale` sets bump
 * frequency, `strength` how deep the relief reads.
 */
export function noiseNormalMap(opts: NormalMapOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 64;
  const scale = Math.max(1, Math.floor(opts.scale ?? 5));
  const rand = rng(opts.seed ?? 7);
  const h = noiseField(s, scale, rand);
  const h2 = noiseField(s, Math.min(s, scale * 2), rand);
  for (let i = 0; i < h.length; i++) h[i] = h[i] * 0.7 + h2[i] * 0.3;
  return heightFieldToNormalMap(h, s, (opts.strength ?? 1) * s * 0.15);
}

/**
 * A brick-relief normal map matching `brickTile`'s layout (two offset courses
 * per tile) — the mortar joints read as real grooves under a moving light.
 * Use it WITH the color tile on the same material so relief and paint line up:
 * `{ texture: brickTile(), normalMap: brickNormalMap() }` (any sizes — both
 * stretch over the same UVs).
 */
export function brickNormalMap(opts: NormalMapOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 64;
  const rand = rng(opts.seed ?? 7);
  const rough = noiseField(s, 12, rand);
  const groove = 0.03; // flat mortar floor half-width (tile units — matches brickTile's 1px inset at 16px)
  const bevel = 0.05;  // ramp from mortar floor up to the brick face
  // Wrapped distance from t to the nearest line in {0, 0.5} (period 1).
  const distToJoint = (t: number): number => {
    const d = t % 0.5;
    return Math.min(d, 0.5 - d);
  };
  const h = new Float32Array(s * s);
  for (let y = 0; y < s; y++) {
    const v = y / s;
    const dv = distToJoint(v);
    const row = Math.floor(v * 2) % 2;
    for (let x = 0; x < s; x++) {
      const u = x / s;
      // Vertical joints: at u=0 for even courses, u=0.5 for odd (brickTile's
      // half-brick offset). One brick per course spans the whole tile width.
      const du = row === 0 ? Math.min(u % 1, 1 - (u % 1)) : Math.abs(u - 0.5);
      const d = Math.min(du, dv);
      let t = Math.min(1, Math.max(0, (d - groove) / bevel));
      t = t * t * (3 - 2 * t); // rounded shoulder, not a hard chamfer
      h[y * s + x] = t + rough[y * s + x] * 0.08; // faint face roughness
    }
  }
  return heightFieldToNormalMap(h, s, (opts.strength ?? 1) * s * 0.15);
}

// ---------------------------------------------------------------------------
// Characters
// ---------------------------------------------------------------------------

/** Options for {@link characterSheet}. */
export interface CharacterOptions {
  /** Frame size in pixels (square). Default `16`. */
  size?: number;
  /** Head and body fill colour. Default `'#ffd166'` (warm yellow). */
  body?: string;
  /** Eye and outline colour. Default `'#26233a'` (near-black). */
  outline?: string;
  /** Leg stroke colour. Default `'#c98aab'` (mauve). */
  leg?: string;
}

/**
 * 4-frame walking character sprite sheet — round-headed figure with swinging legs.
 * The figure **faces right** (a snout pokes past the head's leading edge and the eyes
 * sit on the front of the face), so mirroring it with `flip.x` visibly turns it to face left.
 * Returns a `(4 × size) × size` horizontal strip; use as a `SpriteSheet` with frame width = `size`.
 */
export function characterSheet(opts: CharacterOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const body = opts.body ?? '#ffd166';
  const outline = opts.outline ?? '#26233a';
  const leg = opts.leg ?? '#c98aab';
  const { canvas, ctx } = makeCanvas(s * 4, s);

  const swings = [0, 1, 0, -1]; // leg phase per frame
  for (let f = 0; f < 4; f++) {
    const ox = f * s;
    const cx = ox + s / 2;
    const headR = s * 0.32;
    const headY = s * 0.42;

    // head
    ctx.fillStyle = body;
    ctx.beginPath();
    ctx.arc(cx, headY, headR, 0, Math.PI * 2);
    ctx.fill();

    // snout — a body-coloured wedge poking past the head's right edge, so the
    // figure plainly *faces right*; `flip.x` mirrors the whole sprite to face left.
    ctx.beginPath();
    ctx.moveTo(cx + headR * 0.35, headY - headR * 0.4);
    ctx.lineTo(cx + headR + s * 0.12, headY);
    ctx.lineTo(cx + headR * 0.35, headY + headR * 0.4);
    ctx.closePath();
    ctx.fill();

    // eyes — both shifted onto the leading (right) half of the face
    ctx.fillStyle = outline;
    const eo = s * 0.11;
    ctx.fillRect(Math.round(cx), Math.round(headY - 1), 1, 2);
    ctx.fillRect(Math.round(cx + eo + 1), Math.round(headY - 1), 1, 2);

    // legs
    const sw = swings[f] * (s * 0.14);
    ctx.strokeStyle = leg;
    ctx.lineWidth = Math.max(1, s * 0.09);
    ctx.beginPath();
    const hipY = s * 0.66;
    const footY = s - 1;
    ctx.moveTo(cx - eo, hipY);
    ctx.lineTo(cx - eo - sw, footY);
    ctx.moveTo(cx + eo, hipY);
    ctx.lineTo(cx + eo + sw, footY);
    ctx.stroke();
  }
  return canvas;
}

// ---------------------------------------------------------------------------
// Tiles (tileable textures)
// ---------------------------------------------------------------------------

/** Options shared by all tile generators. */
export interface TileOptions {
  /** Tile edge length in pixels (square). Default `16`. */
  size?: number;
  /** Primary fill colour. */
  base?: string;
  /** Shadow / mortar / grain colour. */
  detail?: string;
  /** Highlight / accent colour. */
  accent?: string;
  /** Integer seed for deterministic random speckle patterns. */
  seed?: number;
}

/** Tileable two-tone checkerboard — THE classic retro-3D scrolling floor (and a fine 2D tile). `base`/`detail` set the two squares. */
export function checkerTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const a = opts.base ?? '#3a4252';
  const b = opts.detail ?? '#2a3040';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = a;
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = b;
  const h = s / 2;
  ctx.fillRect(0, 0, h, h);
  ctx.fillRect(h, h, h, h);
  return canvas;
}

/** Tileable brick wall — offset courses with mortar joints. Use for walls, platforms, dungeon floors. */
export function brickTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const brick = opts.base ?? '#a23e2c';
  const mortar = opts.detail ?? '#3a2420';
  const top = opts.accent ?? '#bb5240';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = mortar;
  ctx.fillRect(0, 0, s, s);

  const rowH = s / 2;
  const brickW = s;
  for (let row = 0; row < 2; row++) {
    const y = row * rowH;
    const offset = row % 2 === 0 ? 0 : -brickW / 2;
    for (let x = offset; x < s; x += brickW) {
      ctx.fillStyle = brick;
      ctx.fillRect(x + 1, y + 1, brickW - 2, rowH - 2);
      ctx.fillStyle = top;
      ctx.fillRect(x + 1, y + 1, brickW - 2, 1); // highlight on top edge
    }
  }
  return canvas;
}

/** Tileable grass — green base with scattered darker flecks and bright blade accents. Use for outdoor ground layers. */
export function grassTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#3a7d34';
  const detail = opts.detail ?? '#2c5f28';
  const accent = opts.accent ?? '#5bbf4f';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);

  const rand = rng(opts.seed ?? 7);
  // darker flecks
  ctx.fillStyle = detail;
  for (let i = 0; i < s; i++) {
    ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  }
  // a few bright blades poking up
  ctx.fillStyle = accent;
  for (let i = 0; i < s / 3; i++) {
    const x = (rand() * s) | 0;
    const y = (rand() * s) | 0;
    ctx.fillRect(x, y, 1, 2);
  }
  return canvas;
}

/** Tileable stone block — grey base with bevel edges and dark speckle cracks. Use for dungeon floors, cave walls. */
export function stoneTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#6b7079';
  const detail = opts.detail ?? '#3f444b';
  const accent = opts.accent ?? '#8a909a';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  // bevel
  ctx.fillStyle = accent;
  ctx.fillRect(0, 0, s, 1);
  ctx.fillRect(0, 0, 1, s);
  ctx.fillStyle = detail;
  ctx.fillRect(0, s - 1, s, 1);
  ctx.fillRect(s - 1, 0, 1, s);
  // specks
  const rand = rng(opts.seed ?? 3);
  ctx.fillStyle = detail;
  for (let i = 0; i < s / 2; i++) {
    ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  }
  return canvas;
}

/** Tileable dirt / earth — brown base with randomised darker and lighter clods. Use for underground or farmland layers. */
export function dirtTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#7a5230';
  const detail = opts.detail ?? '#5b3b21';
  const accent = opts.accent ?? '#9a6b40';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 11);
  for (let i = 0; i < s; i++) {
    ctx.fillStyle = rand() > 0.5 ? detail : accent;
    ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  }
  return canvas;
}

/** Tileable water — blue base with sine-wave ripple rows that tile seamlessly. Use for lakes, rivers, ocean backgrounds. */
export function waterTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#2a6fb0';
  const accent = opts.accent ?? '#7cc0ef';
  const dark = opts.detail ?? '#1f5790';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);

  const amp = Math.max(1, s * 0.06);
  const k = (2 * 2 * Math.PI) / s; // 2 whole periods across width → tiles seamlessly
  for (let row = 0; row < 3; row++) {
    const baseY = s * (0.22 + row * 0.28);
    const phase = row * 1.9;
    for (let x = 0; x < s; x++) {
      const y = Math.round(baseY + Math.sin(x * k + phase) * amp);
      ctx.fillStyle = accent;
      ctx.fillRect(x, y, 1, 1);
      ctx.fillStyle = dark;
      ctx.fillRect(x, y + 1, 1, 1);
    }
  }
  return canvas;
}

/** Tileable sand / desert floor — warm beige with random grain speckles and faint dune ripple lines. */
export function sandTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#e3c98f';
  const detail = opts.detail ?? '#c9a86a';
  const accent = opts.accent ?? '#f4e6bf';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 5);
  for (let i = 0; i < s * 1.5; i++) {
    ctx.fillStyle = rand() > 0.5 ? detail : accent;
    ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  }
  ctx.fillStyle = detail;
  for (let row = 0; row < 2; row++) {
    const baseY = s * (0.35 + row * 0.4);
    for (let x = 0; x < s; x++) {
      const y = Math.round(baseY + Math.sin((x / s) * Math.PI * 2 + row) * s * 0.05);
      ctx.fillRect(x, y, 1, 1);
    }
  }
  return canvas;
}

/** Tileable sci-fi metal panel — bevelled edges, inset panel recess, and corner bolts. Use for space stations, mechs, industrial levels. */
export function metalTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#5a6b7a';
  const light = opts.accent ?? '#90a4b4';
  const dark = opts.detail ?? '#33414d';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  // bevel (light top-left, dark bottom-right)
  ctx.fillStyle = light;
  ctx.fillRect(0, 0, s, 1);
  ctx.fillRect(0, 0, 1, s);
  ctx.fillStyle = dark;
  ctx.fillRect(0, s - 1, s, 1);
  ctx.fillRect(s - 1, 0, 1, s);
  // inset panel line
  ctx.strokeStyle = dark;
  ctx.lineWidth = 1;
  ctx.strokeRect(2.5, 2.5, s - 5, s - 5);
  // corner bolts
  const bolts: number[][] = [[3, 3], [s - 3, 3], [3, s - 3], [s - 3, s - 3]];
  for (const [bx, by] of bolts) {
    ctx.fillStyle = light;
    ctx.beginPath();
    ctx.arc(bx, by, Math.max(1, s * 0.07), 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = dark;
    ctx.fillRect(Math.round(bx) - 0.5, Math.round(by) - 0.5, 1, 1);
  }
  return canvas;
}

/**
 * Thin wooden plank for one-way platforms — visible surface occupies the top ~30 % of the cell, transparent below.
 * The drawn surface aligns with a northward one-way collision line so the player stands exactly on the plank.
 * 2D platforms ONLY: the transparent 70 % makes 3D faces see-through — texture 3D wood with `woodTile` instead.
 */
export function plankTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const wood = opts.base ?? '#b9854c';
  const edge = opts.detail ?? '#6e4a25';
  const top = opts.accent ?? '#d8a868';
  const { canvas, ctx } = makeCanvas(s, s);
  const ph = Math.max(3, Math.round(s * 0.3)); // plank height
  ctx.fillStyle = wood;
  ctx.fillRect(0, 0, s, ph);
  ctx.fillStyle = top;
  ctx.fillRect(0, 0, s, 1); // top highlight (the stand-on surface)
  ctx.fillStyle = edge;
  ctx.fillRect(0, ph - 1, s, 1); // bottom edge
  for (let x = 0; x < s; x += Math.max(4, (s / 2) | 0)) {
    ctx.fillRect(x, 0, 1, ph); // plank seams
  }
  return canvas;
}


/** Tileable wooden crate — plank border with a diagonal brace and highlight. Use for breakable blocks, storage areas. */
export function crateTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#9a6b3a';
  const detail = opts.detail ?? '#5e3f20';
  const accent = opts.accent ?? '#b9854c';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = detail;
  ctx.strokeStyle = detail;
  // border
  ctx.fillRect(0, 0, s, 1);
  ctx.fillRect(0, s - 1, s, 1);
  ctx.fillRect(0, 0, 1, s);
  ctx.fillRect(s - 1, 0, 1, s);
  // planks + diagonal brace
  ctx.fillRect(0, (s / 2) | 0, s, 1);
  ctx.beginPath();
  ctx.moveTo(1, 1);
  ctx.lineTo(s - 1, s - 1);
  ctx.stroke();
  ctx.fillStyle = accent;
  ctx.fillRect(1, 1, s - 2, 1); // top highlight
  return canvas;
}

/** Tileable lava — dark crust with glowing diagonal crack veins and bright ember speckles. Use for hazard / damage zones. */
export function lavaTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const crust = opts.base ?? '#3a140d';
  const glow = opts.accent ?? '#ff7a18';
  const hot = opts.detail ?? '#ffd23f';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = crust;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 9);
  // glowing cracks: a couple of wrapping diagonal veins
  ctx.fillStyle = glow;
  for (let x = 0; x < s; x++) {
    const y1 = Math.round(((x * 1.7) % s));
    const y2 = Math.round(((x * 0.9 + s * 0.5) % s));
    ctx.fillRect(x, y1, 1, 1);
    ctx.fillRect(x, y2, 1, 1);
  }
  ctx.fillStyle = hot; // bright embers
  for (let i = 0; i < s / 3; i++) ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  return canvas;
}

/** Tileable ice — pale blue with a corner sheen and seeded hairline cracks. Use for frozen / slippery surfaces. */
export function iceTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#9fd8f0';
  const light = opts.accent ?? '#e8fbff';
  const dark = opts.detail ?? '#5fa6c9';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = light; // top-left sheen
  ctx.fillRect(0, 0, s, 1);
  ctx.fillRect(0, 0, 1, s);
  ctx.fillStyle = dark; // bottom-right shade + a couple of cracks
  ctx.fillRect(0, s - 1, s, 1);
  ctx.fillRect(s - 1, 0, 1, s);
  const rand = rng(opts.seed ?? 4);
  for (let i = 0; i < 3; i++) {
    let x = (rand() * s) | 0;
    let y = (rand() * s) | 0;
    for (let k = 0; k < 4; k++) { ctx.fillRect(x % s, y % s, 1, 1); x += 1; y += (rand() * 3 - 1) | 0; }
  }
  return canvas;
}

/** Tileable snow — near-white with faint blue-grey flecks and a soft bottom shadow. Use for winter / arctic ground. */
export function snowTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#eef4fb';
  const detail = opts.detail ?? '#cdd8e6';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = detail;
  ctx.fillRect(0, s - 1, s, 1); // soft bottom shade
  const rand = rng(opts.seed ?? 13);
  for (let i = 0; i < s / 2; i++) ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  return canvas;
}

/** Tileable wood — horizontal plank seams with grain marks. Use for floors, bridges, cabin interiors. */
export function woodTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#b9854c';
  const dark = opts.detail ?? '#7a5226';
  const light = opts.accent ?? '#d8a868';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const plankH = s / 2;
  for (let p = 0; p < 2; p++) {
    const y = p * plankH;
    ctx.fillStyle = dark;
    ctx.fillRect(0, y, s, 1); // seam
    ctx.fillStyle = light;
    ctx.fillRect(0, y + 1, s, 1); // highlight under seam
    // grain
    ctx.fillStyle = dark;
    const rand = rng((opts.seed ?? 2) + p);
    for (let x = 0; x < s; x += 3) ctx.fillRect(x, y + 2 + ((rand() * (plankH - 3)) | 0), 2, 1);
  }
  return canvas;
}

/** Tileable cobblestone — four rounded stones with highlighted tops over dark mortar. Use for medieval roads, town squares. */
export function cobbleTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const stone = opts.base ?? '#7d8590';
  const mortar = opts.detail ?? '#33383f';
  const light = opts.accent ?? '#9aa3ad';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = mortar;
  ctx.fillRect(0, 0, s, s);
  const r = s * 0.26;
  const centres = [[s * 0.27, s * 0.27], [s * 0.75, s * 0.3], [s * 0.3, s * 0.76], [s * 0.78, s * 0.78]];
  for (const [cx, cy] of centres) {
    ctx.fillStyle = stone;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = light;
    ctx.beginPath();
    ctx.arc(cx - r * 0.3, cy - r * 0.3, r * 0.35, 0, Math.PI * 2);
    ctx.fill();
  }
  return canvas;
}

/** Tileable gravel — grey base with randomised light and dark grain speckles. Use for paths, riverbanks. */
export function gravelTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#6c7077';
  const dark = opts.detail ?? '#494d53';
  const light = opts.accent ?? '#9398a0';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 17);
  for (let i = 0; i < s * 2.5; i++) {
    const r = rand();
    ctx.fillStyle = r > 0.6 ? light : r > 0.3 ? dark : base;
    ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  }
  return canvas;
}

/** Tileable hedge / dense foliage — dark-green base with randomised light and dark leafy clumps. Use for maze walls, garden borders. */
export function hedgeTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#2f6b2f';
  const dark = opts.detail ?? '#1e4a1e';
  const light = opts.accent ?? '#4f9c43';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 19);
  for (let i = 0; i < s * 3; i++) {
    ctx.fillStyle = rand() > 0.5 ? light : dark;
    const x = (rand() * s) | 0;
    const y = (rand() * s) | 0;
    ctx.fillRect(x, y, 2, 2); // leafy clumps
  }
  return canvas;
}

/** Tileable asphalt road / tarmac — dark grey with randomised grit speckles. Use for city streets, racing tracks. */
export function roadTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#3a3d42';
  const dark = opts.detail ?? '#2a2c30';
  const light = opts.accent ?? '#54585e';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 23);
  for (let i = 0; i < s * 2; i++) {
    ctx.fillStyle = rand() > 0.5 ? light : dark;
    ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  }
  return canvas;
}

/** Tileable circuit board — dark PCB substrate with crossing green traces and a solder pad. Use for sci-fi / cyber levels. */
export function circuitTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#0e2a1e';
  const trace = opts.accent ?? '#3fe07a';
  const dim = opts.detail ?? '#1f5a3a';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = dim;
  ctx.fillRect(s / 2, 0, 1, s); // vertical trace
  ctx.fillRect(0, s / 2, s, 1); // horizontal trace
  ctx.fillStyle = trace;
  ctx.fillRect(s / 2, 0, 1, s / 2); // bright half-traces
  ctx.fillRect(0, s / 2, s / 2, 1);
  ctx.beginPath(); // a solder pad
  ctx.arc(s / 2, s / 2, s * 0.12, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Tileable mud — dark wet earth with elliptical puddle blobs and light grain speckles. Use for swamp, rain-soaked terrain. */
export function mudTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#4e3620';
  const dark = opts.detail ?? '#352314';
  const light = opts.accent ?? '#6a4d30';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  const rand = rng(opts.seed ?? 29);
  ctx.fillStyle = dark;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.ellipse((rand() * s) | 0, (rand() * s) | 0, s * 0.16, s * 0.1, rand() * 3, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = light;
  for (let i = 0; i < s; i++) ctx.fillRect((rand() * s) | 0, (rand() * s) | 0, 1, 1);
  return canvas;
}

/** Tileable marble — pale stone with two sine-wave grey vein lines that wrap seamlessly. Use for palace, temple, luxury interiors. */
export function marbleTile(opts: TileOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const base = opts.base ?? '#e8e6ef';
  const vein = opts.detail ?? '#a9a6bc';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = vein;
  const k = (2 * Math.PI) / s; // 1 full period → wraps
  for (let x = 0; x < s; x++) {
    ctx.fillRect(x, Math.round(s * 0.35 + Math.sin(x * k) * s * 0.18), 1, 1);
    ctx.fillRect(x, Math.round(s * 0.7 + Math.sin(x * k * 2 + 1) * s * 0.1), 1, 1);
  }
  return canvas;
}

// ---------------------------------------------------------------------------
// Tileset packing
// ---------------------------------------------------------------------------

/**
 * Pack equal-size tile canvases into a single horizontal strip image for use with `Tilemap`.
 * Tiles are indexed left-to-right starting at 0; pass the result as the tileset argument to `Tilemap`.
 * @param tiles Array of same-size tile canvases (e.g. from `grassTile`, `stoneTile`, etc.).
 * @returns A `(tileWidth × count) × tileHeight` canvas.
 */
export function tileset(tiles: HTMLCanvasElement[]): HTMLCanvasElement {
  if (!tiles.length) {
    return makeCanvas(1, 1).canvas;
  }
  const tw = tiles[0].width;
  const th = tiles[0].height;
  const { canvas, ctx } = makeCanvas(tw * tiles.length, th);
  for (let i = 0; i < tiles.length; i++) {
    ctx.drawImage(tiles[i], i * tw, 0);
  }
  return canvas;
}

// ---------------------------------------------------------------------------
// Sprites: items, characters, vehicles, scenery
// ---------------------------------------------------------------------------

/** Options shared by all sprite generators. Single-frame sprites return a `size × size` canvas; animated sheets return a horizontal multi-frame strip. */
export interface SpriteOptions {
  /** Sprite size in pixels (square frame). Default `16`. */
  size?: number;
  /** Primary / body colour. */
  color?: string;
  /** Highlight / secondary colour. */
  accent?: string;
  /** Shadow / outline / detail colour. */
  detail?: string;
  /** Integer seed for sprites with randomised elements (e.g. `asteroid`, `building`). */
  seed?: number;
}

// Fill a closed polygon from a list of [x, y] points.
function poly(ctx: CanvasRenderingContext2D, pts: number[][]): void {
  ctx.beginPath();
  pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
  ctx.closePath();
}

function starPoints(
  cx: number,
  cy: number,
  outer: number,
  inner: number,
  n: number = 5,
  rot: number = -Math.PI / 2,
): number[][] {
  const pts: number[][] = [];
  for (let i = 0; i < n * 2; i++) {
    const r = i % 2 ? inner : outer;
    const a = rot + (i * Math.PI) / n;
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
  }
  return pts;
}

// --- Items -----------------------------------------------------------------

/**
 * Spinning gold coin — 4-frame animation strip (face → edge-on → face).
 * Use as a `SpriteSheet` for collectible coins, currency pickups.
 */
export function coinSheet(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const gold = opts.color ?? '#ffcf3f';
  const light = opts.accent ?? '#fff1a8';
  const edge = opts.detail ?? '#c98a1a';
  const { canvas, ctx } = makeCanvas(s * 4, s);
  const widths = [1, 0.55, 0.16, 0.55];
  for (let f = 0; f < 4; f++) {
    const cx = f * s + s / 2;
    const cy = s / 2;
    const r = s * 0.42;
    const rw = Math.max(1, r * widths[f]);
    ctx.fillStyle = f === 2 ? edge : gold;
    ctx.beginPath();
    ctx.ellipse(cx, cy, rw, r, 0, 0, Math.PI * 2);
    ctx.fill();
    if (f !== 2) {
      ctx.strokeStyle = edge;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = light;
      ctx.beginPath();
      ctx.ellipse(cx - rw * 0.3, cy - r * 0.25, Math.max(0.6, rw * 0.35), r * 0.45, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  return canvas;
}

/** Faceted green gem — a single-frame collectible jewel with facet lines. Use for score pickups, RPG loot. */
export function gem(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#48d05a';
  const light = opts.accent ?? '#b6f3bf';
  const dark = opts.detail ?? '#1f7a2e';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const w = s * 0.74;
  const top = s * 0.2;
  const mid = s * 0.44;
  const bot = s * 0.9;
  const L = cx - w / 2;
  const R = cx + w / 2;
  const il = cx - w * 0.26;
  const ir = cx + w * 0.26;
  poly(ctx, [[il, top], [ir, top], [R, mid], [L, mid]]);
  ctx.fillStyle = light;
  ctx.fill();
  poly(ctx, [[L, mid], [R, mid], [cx, bot]]);
  ctx.fillStyle = col;
  ctx.fill();
  ctx.strokeStyle = dark;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(il, top); ctx.lineTo(L, mid);
  ctx.moveTo(ir, top); ctx.lineTo(R, mid);
  ctx.moveTo(cx, mid); ctx.lineTo(cx, bot);
  ctx.moveTo(il, top); ctx.lineTo(cx, mid); ctx.lineTo(ir, top);
  ctx.stroke();
  poly(ctx, [[il, top], [ir, top], [R, mid], [cx, bot], [L, mid]]);
  ctx.stroke();
  return canvas;
}

/** Brilliant-cut diamond — blue-white faceted gem. Use for rare collectibles, shop currency, puzzle gems. */
export function diamond(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#7fe0ff';
  const light = opts.accent ?? '#e6fbff';
  const dark = opts.detail ?? '#39a6c9';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const w = s * 0.66;
  const top = s * 0.16;
  const crown = s * 0.42;
  const bot = s * 0.9;
  const L = cx - w / 2;
  const R = cx + w / 2;
  const tl = cx - w * 0.28;
  const tr = cx + w * 0.28;
  poly(ctx, [[tl, top], [tr, top], [R, crown], [L, crown]]);
  ctx.fillStyle = light;
  ctx.fill();
  poly(ctx, [[L, crown], [R, crown], [cx, bot]]);
  ctx.fillStyle = col;
  ctx.fill();
  ctx.strokeStyle = dark;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(tl, top); ctx.lineTo(L, crown);
  ctx.moveTo(tr, top); ctx.lineTo(R, crown);
  ctx.moveTo(cx, top); ctx.lineTo(cx, crown); ctx.lineTo(cx, bot);
  ctx.moveTo(L, crown); ctx.lineTo(cx, bot); ctx.lineTo(R, crown);
  ctx.stroke();
  poly(ctx, [[tl, top], [tr, top], [R, crown], [cx, bot], [L, crown]]);
  ctx.stroke();
  return canvas;
}

/** Five-point gold star — use for score pickups, ratings, achievement icons. */
export function star(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ffd23f';
  const edge = opts.detail ?? '#e08a00';
  const { canvas, ctx } = makeCanvas(s, s);
  poly(ctx, starPoints(s / 2, s / 2 + s * 0.02, s * 0.46, s * 0.19));
  ctx.fillStyle = col;
  ctx.fill();
  ctx.strokeStyle = edge;
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.lineJoin = 'round';
  ctx.stroke();
  return canvas;
}

/** Red heart — use for lives / health pickups, health HUD icons. */
export function heart(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ff4d6d';
  const light = opts.accent ?? '#ff90a6';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const r = s * 0.23;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(cx - r, s * 0.36, r, Math.PI, 0);
  ctx.arc(cx + r, s * 0.36, r, Math.PI, 0);
  ctx.lineTo(cx, s * 0.86);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = light;
  ctx.beginPath();
  ctx.arc(cx - r, s * 0.34, r * 0.4, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Gold key — bow + shaft + teeth. Use for door / chest unlock collectibles. */
export function key(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const gold = opts.color ?? '#ffcf3f';
  const dark = opts.detail ?? '#c98a1a';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.strokeStyle = gold;
  ctx.fillStyle = gold;
  ctx.lineWidth = Math.max(1.5, s * 0.1);
  ctx.beginPath();
  ctx.arc(s * 0.32, s * 0.32, s * 0.16, 0, Math.PI * 2); // bow
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(s * 0.42, s * 0.42);
  ctx.lineTo(s * 0.78, s * 0.78); // shaft
  ctx.stroke();
  ctx.fillRect(s * 0.66, s * 0.74, s * 0.1, s * 0.14); // teeth
  ctx.fillRect(s * 0.74, s * 0.66, s * 0.14, s * 0.1);
  ctx.fillStyle = dark;
  ctx.beginPath();
  ctx.arc(s * 0.32, s * 0.32, s * 0.05, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

// --- Fruit -----------------------------------------------------------------

/** Red apple with a brown stem and green leaf. Use for food pickups, health items, orchard collectibles. */
export function apple(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#e23d4c';
  const light = opts.accent ?? '#ff7a86';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(cx - s * 0.14, s * 0.58, s * 0.28, 0, Math.PI * 2);
  ctx.arc(cx + s * 0.14, s * 0.58, s * 0.28, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = light;
  ctx.beginPath();
  ctx.ellipse(cx - s * 0.14, s * 0.46, s * 0.07, s * 0.11, -0.4, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#6b3a1e';
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.36);
  ctx.lineTo(cx, s * 0.2);
  ctx.stroke();
  ctx.fillStyle = '#3fae4a';
  ctx.beginPath();
  ctx.ellipse(cx + s * 0.12, s * 0.22, s * 0.12, s * 0.06, -0.6, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Pair of red cherries on a forked green stem. Use for bonus pickups, fruit collectibles. */
export function cherry(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#e02046';
  const light = opts.accent ?? '#ff6a86';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.strokeStyle = '#3fae4a';
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(s * 0.5, s * 0.18);
  ctx.quadraticCurveTo(s * 0.3, s * 0.4, s * 0.32, s * 0.62);
  ctx.moveTo(s * 0.5, s * 0.18);
  ctx.quadraticCurveTo(s * 0.7, s * 0.4, s * 0.68, s * 0.62);
  ctx.stroke();
  for (const dx of [-0.18, 0.18]) {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.arc(s * (0.5 + dx), s * 0.72, s * 0.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = light;
    ctx.beginPath();
    ctx.arc(s * (0.5 + dx) - s * 0.06, s * 0.66, s * 0.06, 0, Math.PI * 2);
    ctx.fill();
  }
  return canvas;
}

// --- RPG gear --------------------------------------------------------------

/** Vertical sword pointing up — tapered blade, cross-guard, leather grip, round pommel. Use for melee weapon pickups. */
export function sword(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const blade = opts.color ?? '#dbe2ea';
  const edge = opts.accent ?? '#9aa7b4';
  const gold = opts.detail ?? '#e0b53a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = blade;
  poly(ctx, [
    [cx, s * 0.06],
    [cx + s * 0.09, s * 0.2],
    [cx + s * 0.06, s * 0.62],
    [cx - s * 0.06, s * 0.62],
    [cx - s * 0.09, s * 0.2],
  ]);
  ctx.fill();
  ctx.fillStyle = edge; // fuller
  ctx.fillRect(cx - 0.5, s * 0.14, 1, s * 0.46);
  ctx.fillStyle = gold; // cross-guard
  ctx.fillRect(cx - s * 0.22, s * 0.6, s * 0.44, s * 0.07);
  ctx.fillStyle = '#7a4a24'; // grip
  ctx.fillRect(cx - s * 0.05, s * 0.66, s * 0.1, s * 0.22);
  ctx.fillStyle = gold; // pommel
  ctx.beginPath();
  ctx.arc(cx, s * 0.9, s * 0.07, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Heater shield with a gold rim and cross emblem — use for defensive item pickups, knight / warrior characters. */
export function shield(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const face = opts.color ?? '#c0492f';
  const rim = opts.detail ?? '#d8b24a';
  const boss = opts.accent ?? '#ece4d4';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = rim;
  poly(ctx, [[s * 0.16, s * 0.14], [s * 0.84, s * 0.14], [s * 0.84, s * 0.5], [cx, s * 0.92], [s * 0.16, s * 0.5]]);
  ctx.fill();
  ctx.fillStyle = face;
  poly(ctx, [[s * 0.25, s * 0.21], [s * 0.75, s * 0.21], [s * 0.75, s * 0.49], [cx, s * 0.82], [s * 0.25, s * 0.49]]);
  ctx.fill();
  ctx.fillStyle = boss; // cross emblem
  ctx.fillRect(cx - s * 0.04, s * 0.27, s * 0.08, s * 0.36);
  ctx.fillRect(s * 0.33, s * 0.37, s * 0.34, s * 0.08);
  return canvas;
}

// --- Characters ------------------------------------------------------------

interface PersonPalette {
  skin: string;
  shirt: string;
  pants: string;
  cap: string;
}

// Draw one side-view person pose into a frame at x-offset ox.
function drawPerson(
  ctx: CanvasRenderingContext2D,
  ox: number,
  s: number,
  legSwing: number,
  armSwing: number,
  bob: number,
  jump: boolean,
  p: PersonPalette,
): void {
  const cx = ox + s * 0.5;
  const headR = s * 0.13;
  const headY = s * 0.2 - bob;
  const shoulderY = s * 0.37 - bob;
  const hipY = s * 0.62 - bob;
  const footY = s * 0.88;
  const shoe = '#3a2a1a';

  let frontX: number;
  let backX: number;
  let frontY: number;
  let backY: number;
  if (jump) {
    frontX = cx + s * 0.16; frontY = hipY + s * 0.14;
    backX = cx - s * 0.05; backY = hipY + s * 0.2;
  } else {
    frontX = cx + legSwing * s * 0.16; frontY = footY;
    backX = cx - legSwing * s * 0.16; backY = footY;
  }

  ctx.strokeStyle = p.pants;
  ctx.lineWidth = Math.max(1.6, s * 0.12);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx, hipY); ctx.lineTo(frontX, frontY);
  ctx.moveTo(cx, hipY); ctx.lineTo(backX, backY);
  ctx.stroke();

  ctx.strokeStyle = shoe;
  ctx.lineWidth = Math.max(1.6, s * 0.13);
  ctx.beginPath();
  ctx.moveTo(backX - s * 0.02, backY); ctx.lineTo(backX + s * 0.1, backY);
  ctx.moveTo(frontX - s * 0.02, frontY); ctx.lineTo(frontX + s * 0.1, frontY);
  ctx.stroke();

  ctx.fillStyle = p.shirt;
  ctx.fillRect(cx - s * 0.11, shoulderY, s * 0.22, hipY - shoulderY + s * 0.02);

  ctx.strokeStyle = p.skin;
  ctx.lineWidth = Math.max(1.3, s * 0.09);
  ctx.beginPath();
  if (jump) {
    ctx.moveTo(cx + s * 0.02, shoulderY + s * 0.02); ctx.lineTo(cx + s * 0.16, shoulderY - s * 0.05);
    ctx.moveTo(cx - s * 0.02, shoulderY + s * 0.02); ctx.lineTo(cx - s * 0.11, shoulderY - s * 0.02);
  } else {
    ctx.moveTo(cx, shoulderY + s * 0.02); ctx.lineTo(cx + armSwing * s * 0.13, shoulderY + s * 0.18);
    ctx.moveTo(cx, shoulderY + s * 0.02); ctx.lineTo(cx - armSwing * s * 0.13, shoulderY + s * 0.18);
  }
  ctx.stroke();

  ctx.fillStyle = p.skin;
  ctx.beginPath();
  ctx.arc(cx + s * 0.02, headY, headR, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = p.cap;
  ctx.beginPath();
  ctx.arc(cx + s * 0.02, headY, headR, Math.PI, 0);
  ctx.fill();
  ctx.fillRect(cx + s * 0.02, headY - headR * 0.55, headR * 1.5, Math.max(1, s * 0.06));
  ctx.fillStyle = '#222';
  ctx.fillRect(Math.round(cx + headR * 0.6), Math.round(headY - 1), 1, 2);
}

/**
 * Side-view running person (player character) — 6-frame strip: frame 0 idle, frames 1–4 run cycle, frame 5 jump.
 * Use with `addAnim('run', t, [1,2,3,4])`. Default palette: red cap, blue trousers.
 */
export function personSheet(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const shirt = opts.color ?? '#d8413a';
  const p: PersonPalette = {
    skin: opts.accent ?? '#f1c27d',
    shirt,
    cap: shirt,
    pants: opts.detail ?? '#2b53c0',
  };
  const { canvas, ctx } = makeCanvas(s * 6, s);
  drawPerson(ctx, 0, s, 0, 0, 0, false, p); // idle
  const legs = [1, 0, -1, 0];
  const bobs = [0, s * 0.03, 0, s * 0.03];
  for (let i = 0; i < 4; i++) {
    drawPerson(ctx, (i + 1) * s, s, legs[i], -legs[i], bobs[i], false, p); // run
  }
  drawPerson(ctx, 5 * s, s, 0, 0, s * 0.04, true, p); // jump
  return canvas;
}

/** The Anthropic Claude mascot — clay-orange sunburst disc with a friendly face. */
export function claude(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const clay = opts.color ?? '#d97757';
  const ink = opts.detail ?? '#2b2118';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s * 0.52;
  const r = s * 0.28;
  ctx.strokeStyle = clay;
  ctx.lineWidth = Math.max(1.4, s * 0.09);
  ctx.lineCap = 'round';
  for (let i = 0; i < 12; i++) {
    const a = (i * Math.PI) / 6;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * r * 0.95, cy + Math.sin(a) * r * 0.95);
    ctx.lineTo(cx + Math.cos(a) * r * 1.5, cy + Math.sin(a) * r * 1.5);
    ctx.stroke();
  }
  ctx.fillStyle = clay;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(cx - r * 0.38, cy - r * 0.05, r * 0.15, 0, Math.PI * 2);
  ctx.arc(cx + r * 0.38, cy - r * 0.05, r * 0.15, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.arc(cx, cy + r * 0.1, r * 0.42, 0.15 * Math.PI, 0.85 * Math.PI);
  ctx.stroke();
  return canvas;
}

/** Pac-Man-style ghost — rounded top with a scalloped skirt and dot eyes. Use for enemy characters in maze or horror games. */
export function ghost(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ff6ad5';
  const ink = opts.detail ?? '#1b2a4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const r = s * 0.34;
  const topY = s * 0.2;
  const by = topY + r + r * 0.95;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(cx, topY + r, r, Math.PI, 0);
  ctx.lineTo(cx + r, by);
  const n = 3;
  const step = (2 * r) / n;
  for (let i = 0; i < n; i++) {
    const x = cx + r - step * i;
    ctx.lineTo(x - step / 2, by - r * 0.28);
    ctx.lineTo(x - step, by);
  }
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(cx - r * 0.4, topY + r * 0.95, r * 0.3, 0, Math.PI * 2);
  ctx.arc(cx + r * 0.4, topY + r * 0.95, r * 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(cx - r * 0.28, topY + r * 1.05, r * 0.14, 0, Math.PI * 2);
  ctx.arc(cx + r * 0.52, topY + r * 1.05, r * 0.14, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Green alien — rounded head with large almond eyes, antennae with bulb tips. Use for space / sci-fi enemy characters. */
export function alien(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#5bff7a';
  const ink = opts.detail ?? '#15402a';
  const glint = opts.accent ?? '#ffffff';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;

  ctx.strokeStyle = col;
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(cx - s * 0.14, s * 0.34);
  ctx.lineTo(cx - s * 0.24, s * 0.1);
  ctx.moveTo(cx + s * 0.14, s * 0.34);
  ctx.lineTo(cx + s * 0.24, s * 0.1);
  ctx.stroke();
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(cx - s * 0.24, s * 0.1, s * 0.06, 0, Math.PI * 2);
  ctx.arc(cx + s * 0.24, s * 0.1, s * 0.06, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.ellipse(cx, s * 0.56, s * 0.35, s * 0.33, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.ellipse(cx - s * 0.14, s * 0.56, s * 0.1, s * 0.15, 0.3, 0, Math.PI * 2);
  ctx.ellipse(cx + s * 0.14, s * 0.56, s * 0.1, s * 0.15, -0.3, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = glint;
  ctx.beginPath();
  ctx.arc(cx - s * 0.17, s * 0.49, s * 0.035, 0, Math.PI * 2);
  ctx.arc(cx + s * 0.11, s * 0.49, s * 0.035, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Slime blob enemy — rounded teardrop body with dot eyes. Use for basic enemy sprites in platformers or RPGs. */
export function slime(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#52c7e6';
  const light = opts.accent ?? '#a6ecf7';
  const ink = opts.detail ?? '#16384a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(s * 0.12, s * 0.85);
  ctx.quadraticCurveTo(s * 0.05, s * 0.3, cx, s * 0.22);
  ctx.quadraticCurveTo(s * 0.95, s * 0.3, s * 0.88, s * 0.85);
  ctx.quadraticCurveTo(cx, s * 0.74, s * 0.12, s * 0.85);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = light;
  ctx.beginPath();
  ctx.ellipse(cx - s * 0.16, s * 0.4, s * 0.08, s * 0.12, -0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(cx - s * 0.14, s * 0.55, s * 0.06, 0, Math.PI * 2);
  ctx.arc(cx + s * 0.14, s * 0.55, s * 0.06, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Blocky robot — rectangular head and body with glowing blue eyes and a centre antenna. Use for sci-fi enemies or NPCs. */
export function robot(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const body = opts.color ?? '#9aa7b4';
  const dark = opts.detail ?? '#5a6672';
  const eye = opts.accent ?? '#6ad5ff';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.strokeStyle = dark;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(s / 2, s * 0.06);
  ctx.lineTo(s / 2, s * 0.18); // antenna
  ctx.stroke();
  ctx.fillStyle = eye;
  ctx.beginPath();
  ctx.arc(s / 2, s * 0.05, s * 0.05, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = body;
  ctx.fillRect(s * 0.24, s * 0.2, s * 0.52, s * 0.42); // head
  ctx.fillRect(s * 0.3, s * 0.6, s * 0.4, s * 0.3); // body
  ctx.fillStyle = dark;
  ctx.fillRect(s * 0.12, s * 0.64, s * 0.18, s * 0.1); // arms
  ctx.fillRect(s * 0.7, s * 0.64, s * 0.18, s * 0.1);
  ctx.fillStyle = eye;
  ctx.fillRect(s * 0.32, s * 0.32, s * 0.14, s * 0.12); // eyes
  ctx.fillRect(s * 0.54, s * 0.32, s * 0.14, s * 0.12);
  ctx.fillStyle = dark;
  ctx.fillRect(s * 0.36, s * 0.5, s * 0.28, s * 0.04); // mouth
  return canvas;
}

// --- Vehicles --------------------------------------------------------------

/** Top-down arcade spaceship pointing up — swept hull, swept wings, cockpit dome, engine exhaust. Use for shoot-em-up player ships. */
export function spaceship(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const body = opts.color ?? '#cfd8e3';
  const wing = opts.detail ?? '#7d8a9c';
  const glass = opts.accent ?? '#5bd6ff';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = wing;
  poly(ctx, [[s * 0.08, s * 0.86], [s * 0.3, s * 0.5], [s * 0.3, s * 0.86]]);
  ctx.fill();
  poly(ctx, [[s * 0.92, s * 0.86], [s * 0.7, s * 0.5], [s * 0.7, s * 0.86]]);
  ctx.fill();
  ctx.fillStyle = body;
  poly(ctx, [[cx, s * 0.08], [s * 0.72, s * 0.82], [cx, s * 0.7], [s * 0.28, s * 0.82]]);
  ctx.fill();
  ctx.fillStyle = glass;
  ctx.beginPath();
  ctx.arc(cx, s * 0.42, s * 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ff8a1e';
  ctx.fillRect(cx - s * 0.06, s * 0.82, s * 0.12, s * 0.12); // thruster
  return canvas;
}

/** Side-view rocket pointing up — tapered body, delta fins, porthole, flame plume. Use for launch sequences, missile sprites. */
export function rocket(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const body = opts.color ?? '#eef2f6';
  const fin = opts.detail ?? '#e23d4c';
  const glass = opts.accent ?? '#5bd6ff';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = fin;
  poly(ctx, [[s * 0.3, s * 0.62], [s * 0.16, s * 0.86], [s * 0.3, s * 0.82]]);
  ctx.fill();
  poly(ctx, [[s * 0.7, s * 0.62], [s * 0.84, s * 0.86], [s * 0.7, s * 0.82]]);
  ctx.fill();
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.06);
  ctx.quadraticCurveTo(s * 0.72, s * 0.4, s * 0.68, s * 0.82);
  ctx.lineTo(s * 0.32, s * 0.82);
  ctx.quadraticCurveTo(s * 0.28, s * 0.4, cx, s * 0.06);
  ctx.fill();
  ctx.fillStyle = glass;
  ctx.beginPath();
  ctx.arc(cx, s * 0.4, s * 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ff8a1e';
  poly(ctx, [[s * 0.4, s * 0.82], [cx, s * 0.98], [s * 0.6, s * 0.82]]);
  ctx.fill();
  return canvas;
}

/** Side-view car — body, windscreen, headlight, two wheels with hub caps. Use for racing or driving games. */
export function car(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const body = opts.color ?? '#e23d4c';
  const glass = opts.accent ?? '#bfe6ff';
  const tyre = opts.detail ?? '#23262e';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = body;
  ctx.fillRect(s * 0.06, s * 0.5, s * 0.88, s * 0.22); // lower body
  poly(ctx, [[s * 0.26, s * 0.5], [s * 0.36, s * 0.3], [s * 0.66, s * 0.3], [s * 0.76, s * 0.5]]);
  ctx.fill();
  ctx.fillStyle = glass;
  poly(ctx, [[s * 0.32, s * 0.48], [s * 0.39, s * 0.34], [s * 0.62, s * 0.34], [s * 0.68, s * 0.48]]);
  ctx.fill();
  ctx.fillStyle = '#ffd23f';
  ctx.fillRect(s * 0.9, s * 0.54, s * 0.06, s * 0.08); // headlight
  ctx.fillStyle = tyre;
  for (const wx of [0.3, 0.72]) {
    ctx.beginPath();
    ctx.arc(s * wx, s * 0.74, s * 0.12, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#8a929c';
    ctx.beginPath();
    ctx.arc(s * wx, s * 0.74, s * 0.05, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = tyre;
  }
  return canvas;
}

/** Side-view lorry / truck — trailer box, cab with window, three wheels. Use for delivery or road obstacle sprites. */
export function truck(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const cab = opts.color ?? '#2f80d9';
  const box = opts.accent ?? '#e8ecf0';
  const tyre = opts.detail ?? '#23262e';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = box;
  ctx.fillRect(s * 0.06, s * 0.24, s * 0.56, s * 0.42); // trailer box
  ctx.strokeStyle = '#b6bcc4';
  ctx.lineWidth = 1;
  ctx.strokeRect(s * 0.06, s * 0.24, s * 0.56, s * 0.42);
  ctx.fillStyle = cab;
  ctx.fillRect(s * 0.64, s * 0.4, s * 0.3, s * 0.26); // cab
  poly(ctx, [[s * 0.64, s * 0.4], [s * 0.7, s * 0.26], [s * 0.84, s * 0.26], [s * 0.84, s * 0.4]]);
  ctx.fill();
  ctx.fillStyle = '#bfe6ff';
  ctx.fillRect(s * 0.72, s * 0.3, s * 0.1, s * 0.1); // window
  ctx.fillStyle = tyre;
  for (const wx of [0.24, 0.5, 0.78]) {
    ctx.beginPath();
    ctx.arc(s * wx, s * 0.72, s * 0.11, 0, Math.PI * 2);
    ctx.fill();
  }
  return canvas;
}

// --- Scenery & FX ----------------------------------------------------------

/** Sun with 8 radiating rays and a smiling face. Use for sky decoration, weather indicators. */
export function sun(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ffd23f';
  const ray = opts.accent ?? '#ffb01e';
  const ink = opts.detail ?? '#b06a00';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  const r = s * 0.26;
  ctx.strokeStyle = ray;
  ctx.lineWidth = Math.max(1.2, s * 0.07);
  ctx.lineCap = 'round';
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * r * 1.2, cy + Math.sin(a) * r * 1.2);
    ctx.lineTo(cx + Math.cos(a) * r * 1.7, cy + Math.sin(a) * r * 1.7);
    ctx.stroke();
  }
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(cx - r * 0.4, cy - r * 0.1, r * 0.12, 0, Math.PI * 2);
  ctx.arc(cx + r * 0.4, cy - r * 0.1, r * 0.12, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.arc(cx, cy + r * 0.05, r * 0.45, 0.15 * Math.PI, 0.85 * Math.PI);
  ctx.stroke();
  return canvas;
}

function drawFlame(
  ctx: CanvasRenderingContext2D,
  bx: number,
  by: number,
  w: number,
  h: number,
  col: string,
): void {
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(bx, by);
  ctx.quadraticCurveTo(bx - w, by - h * 0.5, bx, by - h);
  ctx.quadraticCurveTo(bx + w, by - h * 0.5, bx, by);
  ctx.fill();
}

/**
 * Animated wall torch — 3-frame flicker strip (flame sways left / centre / right).
 * Use as a `SpriteSheet` for dungeon, cave, or castle wall light sources.
 */
export function torchSheet(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const wood = opts.detail ?? '#7a4a24';
  const outer = '#ff5a1e';
  const mid = '#ff9a1e';
  const inner = opts.color ?? '#ffe06a';
  const { canvas, ctx } = makeCanvas(s * 3, s);
  for (let f = 0; f < 3; f++) {
    const cx = f * s + s / 2;
    ctx.fillStyle = wood;
    ctx.fillRect(cx - s * 0.08, s * 0.55, s * 0.16, s * 0.4);
    ctx.fillStyle = '#caa11e';
    ctx.fillRect(cx - s * 0.12, s * 0.5, s * 0.24, s * 0.08); // cup
    const sway = (f - 1) * s * 0.07;
    const hh = s * (0.46 + 0.04 * (f % 2));
    drawFlame(ctx, cx + sway, s * 0.52, s * 0.3, hh, outer);
    drawFlame(ctx, cx + sway * 0.5, s * 0.52, s * 0.2, hh * 0.78, mid);
    drawFlame(ctx, cx, s * 0.52, s * 0.1, hh * 0.5, inner);
  }
  return canvas;
}

/** Round bomb with a curved lit fuse and glinting body. Use for throwable weapons, hazards, countdown objects. */
export function bomb(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#2b2f38';
  const shine = opts.accent ?? '#6b7280';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(cx, s * 0.62, s * 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = shine;
  ctx.beginPath();
  ctx.arc(cx - s * 0.1, s * 0.52, s * 0.07, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#8a929c';
  ctx.fillRect(cx - s * 0.08, s * 0.28, s * 0.16, s * 0.08); // cap
  ctx.strokeStyle = '#caa11e';
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.28);
  ctx.quadraticCurveTo(s * 0.75, s * 0.18, s * 0.72, s * 0.06);
  ctx.stroke();
  ctx.fillStyle = '#ff8a1e';
  ctx.beginPath();
  ctx.arc(s * 0.72, s * 0.06, s * 0.06, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Round deciduous tree — brown trunk, dark green foliage cluster. Use for forest / outdoor scenery. */
export function tree(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const leaf = opts.color ?? '#3fae4a';
  const dark = opts.accent ?? '#2c7d36';
  const trunk = opts.detail ?? '#7a4a24';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = trunk;
  ctx.fillRect(cx - s * 0.07, s * 0.6, s * 0.14, s * 0.34);
  ctx.fillStyle = dark;
  ctx.beginPath();
  ctx.arc(cx, s * 0.4, s * 0.34, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = leaf;
  ctx.beginPath();
  ctx.arc(cx - s * 0.12, s * 0.36, s * 0.2, 0, Math.PI * 2);
  ctx.arc(cx + s * 0.14, s * 0.42, s * 0.18, 0, Math.PI * 2);
  ctx.arc(cx, s * 0.26, s * 0.18, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Fluffy white cloud — three overlapping circular puffs. Use for sky backgrounds, parallax layers, weather sprites. */
export function cloud(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#eef3f8';
  const shade = opts.detail ?? '#cdd8e2';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.fillStyle = shade;
  ctx.beginPath();
  ctx.arc(s * 0.34, s * 0.62, s * 0.2, 0, Math.PI * 2);
  ctx.arc(s * 0.54, s * 0.66, s * 0.22, 0, Math.PI * 2);
  ctx.arc(s * 0.72, s * 0.6, s * 0.18, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(s * 0.36, s * 0.5, s * 0.18, 0, Math.PI * 2);
  ctx.arc(s * 0.56, s * 0.46, s * 0.22, 0, Math.PI * 2);
  ctx.arc(s * 0.74, s * 0.52, s * 0.16, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

// Draw a filled circle.
function disc(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, fill: string): void {
  ctx.fillStyle = fill;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
}

