/** Orange citrus fruit with a highlight and green leaf. Use for food pickups, collectible items. */
export function orange(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ff8c1a';
  const light = opts.accent ?? '#ffc070';
  const leaf = opts.detail ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s * 0.58, s * 0.34, col);
  disc(ctx, cx - s * 0.12, s * 0.46, s * 0.1, light);
  ctx.fillStyle = leaf;
  ctx.beginPath();
  ctx.ellipse(cx + s * 0.1, s * 0.24, s * 0.1, s * 0.05, -0.6, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Yellow lemon with pointed nubs and a highlight. Use for food pickups, sour-themed collectibles. */
export function lemon(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#f2d11e';
  const light = opts.accent ?? '#fbef9a';
  const tip = opts.detail ?? '#d9b414';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.55, s * 0.36, s * 0.24, 0, 0, Math.PI * 2);
  ctx.fill();
  disc(ctx, s * 0.16, s * 0.55, s * 0.05, tip); // nub ends
  disc(ctx, s * 0.84, s * 0.55, s * 0.05, tip);
  ctx.fillStyle = light;
  ctx.beginPath();
  ctx.ellipse(cx - s * 0.08, s * 0.46, s * 0.12, s * 0.06, -0.3, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Purple bunch of grapes — three rows of berries narrowing to a point, stem and leaf. Use for fruit pickups, vineyard-themed games. */
export function grapes(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#7d4fc7';
  const light = opts.accent ?? '#a884e0';
  const leaf = opts.detail ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  // stem + leaf
  ctx.strokeStyle = '#6b3a1e';
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.28);
  ctx.lineTo(cx, s * 0.12);
  ctx.stroke();
  ctx.fillStyle = leaf;
  ctx.beginPath();
  ctx.ellipse(cx + s * 0.12, s * 0.14, s * 0.1, s * 0.05, -0.5, 0, Math.PI * 2);
  ctx.fill();
  // bunch: rows of berries narrowing downward
  const r = s * 0.11;
  const rows = [
    [cx - r * 1.6, cx, cx + r * 1.6],
    [cx - r * 0.9, cx + r * 0.9],
    [cx],
  ];
  for (let ri = 0; ri < rows.length; ri++) {
    const y = s * 0.36 + ri * r * 1.5;
    for (const x of rows[ri]) disc(ctx, x, y, r, col);
  }
  disc(ctx, cx - r * 1.6 - r * 0.3, s * 0.36 - r * 0.3, r * 0.35, light); // a couple of highlights
  disc(ctx, cx - r * 0.3, s * 0.36 + r * 1.5 - r * 0.3, r * 0.35, light);
  return canvas;
}

/** Yellow banana — thick crescent arc with brown tip dots. Use for food pickups, jungle-themed collectibles. */
export function banana(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#f4d03f';
  const tip = opts.detail ?? '#6e4a25';
  const { canvas, ctx } = makeCanvas(s, s);
  ctx.strokeStyle = col;
  ctx.lineWidth = s * 0.2;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(s / 2, s * 0.18, s * 0.44, Math.PI * 0.18, Math.PI * 0.82);
  ctx.stroke();
  disc(ctx, s / 2 + Math.cos(Math.PI * 0.18) * s * 0.44, s * 0.18 + Math.sin(Math.PI * 0.18) * s * 0.44, s * 0.05, tip);
  disc(ctx, s / 2 + Math.cos(Math.PI * 0.82) * s * 0.44, s * 0.18 + Math.sin(Math.PI * 0.82) * s * 0.44, s * 0.05, tip);
  return canvas;
}

/** Red strawberry with a star-shaped calyx and seed dots. Use for food pickups, garden or farming game collectibles. */
export function strawberry(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#e23048';
  const seed = opts.accent ?? '#ffe08a';
  const leaf = opts.detail ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  // body: rounded top tapering to a point
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(s * 0.2, s * 0.42);
  ctx.quadraticCurveTo(cx, s * 0.26, s * 0.8, s * 0.42);
  ctx.quadraticCurveTo(cx, s * 1.02, s * 0.2, s * 0.42);
  ctx.closePath();
  ctx.fill();
  // calyx
  ctx.fillStyle = leaf;
  poly(ctx, starPoints(cx, s * 0.36, s * 0.18, s * 0.07, 5, -Math.PI / 2));
  ctx.fill();
  // seeds
  ctx.fillStyle = seed;
  const sp = [[0.42, 0.55], [0.58, 0.55], [0.5, 0.66], [0.38, 0.66], [0.62, 0.66], [0.5, 0.78]];
  for (const [fx, fy] of sp) ctx.fillRect(Math.round(s * fx), Math.round(s * fy), 1, 1);
  return canvas;
}

/** Green pear — bulb body with narrow neck, brown stem, highlight. Use for food pickups, orchard collectibles. */
export function pear(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#a6c44a';
  const light = opts.accent ?? '#cfe07a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s * 0.64, s * 0.27, col); // bulb
  disc(ctx, cx, s * 0.4, s * 0.16, col); // neck
  ctx.fillStyle = col;
  ctx.fillRect(cx - s * 0.16, s * 0.4, s * 0.32, s * 0.24); // join the two
  ctx.strokeStyle = '#6b3a1e';
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.26);
  ctx.lineTo(cx + s * 0.03, s * 0.14);
  ctx.stroke();
  disc(ctx, cx - s * 0.1, s * 0.56, s * 0.08, light); // highlight
  return canvas;
}

/** Green watermelon with dark stripe arcs and a flesh-coloured sheen. Use for summer / tropical food pickups. */
export function watermelon(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const rind = opts.color ?? '#3a8f3a';
  const stripe = opts.detail ?? '#256025';
  const flesh = opts.accent ?? '#ff5a6a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s / 2, s * 0.4, rind);
  // dark stripes (curved verticals)
  ctx.strokeStyle = stripe;
  ctx.lineWidth = Math.max(1, s * 0.06);
  for (const off of [-0.2, 0, 0.2]) {
    ctx.beginPath();
    ctx.moveTo(cx + off * s, s * 0.14);
    ctx.quadraticCurveTo(cx + off * s * 1.6, s / 2, cx + off * s, s * 0.86);
    ctx.stroke();
  }
  disc(ctx, cx - s * 0.14, s * 0.36, s * 0.06, '#bfe6a0'); // sheen
  return canvas;
}

/** Peach / apricot with a vertical crease arc, highlight, and green leaf. Use for food pickups in orchard or farm games. */
export function peach(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ffae7a';
  const light = opts.accent ?? '#ffd2b0';
  const crease = opts.detail ?? '#e8895c';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s * 0.56, s * 0.34, col);
  ctx.strokeStyle = crease; // vertical crease
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.arc(cx + s * 0.06, s * 0.56, s * 0.32, -Math.PI * 0.42, Math.PI * 0.42);
  ctx.stroke();
  disc(ctx, cx - s * 0.12, s * 0.44, s * 0.09, light);
  ctx.fillStyle = '#3fae4a'; // leaf
  ctx.beginPath();
  ctx.ellipse(cx + s * 0.08, s * 0.24, s * 0.09, s * 0.045, -0.6, 0, Math.PI * 2);
  ctx.fill();
  return canvas;
}

/** Purple plum — oval body with a crease arc and highlight. Use for food pickups, orchard collectibles. */
export function plum(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#7a3f9e';
  const light = opts.accent ?? '#a86cc7';
  const crease = opts.detail ?? '#5a2d77';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.56, s * 0.3, s * 0.34, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = crease;
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.arc(cx + s * 0.05, s * 0.56, s * 0.3, -Math.PI * 0.45, Math.PI * 0.45);
  ctx.stroke();
  disc(ctx, cx - s * 0.1, s * 0.42, s * 0.08, light);
  return canvas;
}

