/** Flying saucer / UFO — metallic disc body with a glass dome and three under-lights. Use for alien invader, escort, or backdrop sprites. */
export function ufo(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#9aa7b4';
  const dome = opts.accent ?? '#7fd0ff';
  const light = opts.detail ?? '#ffd23f';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col; // saucer body
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.6, s * 0.42, s * 0.15, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = dome; // glass dome
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.52, s * 0.2, s * 0.18, 0, Math.PI, 0);
  ctx.fill();
  ctx.fillStyle = light; // under-lights
  for (const o of [-0.22, 0, 0.22]) disc(ctx, cx + o * s, s * 0.68, s * 0.04, light);
  return canvas;
}

/** Planet with two equatorial band stripes and a polar highlight. Use for space backgrounds, level-select screens. */
export function planet(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#c86b4a';
  const band = opts.detail ?? '#9c4e34';
  const light = opts.accent ?? '#e89a78';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  const r = s * 0.36;
  disc(ctx, cx, cy, r, col);
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.clip();
  ctx.fillStyle = band;
  for (const by of [0.42, 0.62]) {
    ctx.beginPath();
    ctx.ellipse(cx, s * by, r * 1.1, r * 0.16, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  disc(ctx, cx - r * 0.4, cy - r * 0.4, r * 0.22, light); // highlight
  return canvas;
}

/** Saturn-style ringed planet — planet disc with a tilted elliptical ring drawn front and back. Use for space scenery, level-select worlds. */
export function ringedPlanet(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#e0c060';
  const ringCol = opts.accent ?? '#bfa9d6';
  const light = opts.detail ?? '#fff0b0';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  ctx.strokeStyle = ringCol;
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath(); // full ring (the back shows above the planet)
  ctx.ellipse(cx, cy, s * 0.46, s * 0.17, -0.25, 0, Math.PI * 2);
  ctx.stroke();
  disc(ctx, cx, cy, s * 0.26, col); // planet (hides the ring's centre)
  disc(ctx, cx - s * 0.09, cy - s * 0.09, s * 0.08, light);
  ctx.beginPath(); // front half of the ring, drawn over the planet
  ctx.ellipse(cx, cy, s * 0.46, s * 0.17, -0.25, 0, Math.PI);
  ctx.stroke();
  return canvas;
}

/** Grey moon disc with four seeded craters. Use for space backgrounds, night-scene decoration. */
export function moon(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#cfd3da';
  const crater = opts.detail ?? '#a3a8b2';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s / 2, s * 0.36, col);
  for (const [ox, oy, cr] of [[-0.1, -0.1, 0.08], [0.14, 0.06, 0.06], [-0.04, 0.16, 0.05], [0.08, -0.16, 0.04]]) {
    disc(ctx, cx + ox * s, s / 2 + oy * s, cr * s, crater);
  }
  return canvas;
}

/** Seeded irregular asteroid with two craters — shape varies per `seed`. Use for space obstacle sprites. */
export function asteroid(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#8a8f98';
  const crater = opts.detail ?? '#5f636b';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  const rand = rng(opts.seed ?? 7);
  const n = 9;
  const pts: number[][] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const r = s * (0.28 + rand() * 0.12);
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
  }
  poly(ctx, pts);
  ctx.fillStyle = col;
  ctx.fill();
  disc(ctx, cx - s * 0.08, cy - s * 0.04, s * 0.06, crater); // craters
  disc(ctx, cx + s * 0.1, cy + s * 0.08, s * 0.05, crater);
  return canvas;
}

/** Space satellite — rectangular body flanked by two solar panels with grid lines and a dish antenna. Use for sci-fi / space scenery. */
export function satellite(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const body = opts.color ?? '#c7ccd4';
  const panel = opts.accent ?? '#2f6bff';
  const dark = opts.detail ?? '#3a3f47';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  // solar panels
  ctx.fillStyle = panel;
  ctx.fillRect(s * 0.06, cy - s * 0.1, s * 0.26, s * 0.2);
  ctx.fillRect(s * 0.68, cy - s * 0.1, s * 0.26, s * 0.2);
  ctx.fillStyle = dark; // panel grid
  for (const px of [0.14, 0.22, 0.74, 0.82]) ctx.fillRect(s * px, cy - s * 0.1, 1, s * 0.2);
  // body
  ctx.fillStyle = body;
  ctx.fillRect(cx - s * 0.12, cy - s * 0.13, s * 0.24, s * 0.26);
  // dish + antenna
  ctx.strokeStyle = dark;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx, cy - s * 0.13);
  ctx.lineTo(cx, cy - s * 0.28);
  ctx.stroke();
  disc(ctx, cx, cy - s * 0.3, s * 0.06, body);
  return canvas;
}

