/** Crab-style space invader — oval body with side claws, three bottom legs, and dot eyes. Use for shoot-em-up enemy sprites. */
export function crabAlien(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ff5bd0';
  const ink = opts.detail ?? '#3a1030';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.5, s * 0.34, s * 0.24, 0, 0, Math.PI * 2); // body
  ctx.fill();
  disc(ctx, s * 0.14, s * 0.46, s * 0.1, col); // claws
  disc(ctx, s * 0.86, s * 0.46, s * 0.1, col);
  ctx.fillStyle = ink; // eyes
  disc(ctx, cx - s * 0.12, s * 0.48, s * 0.06, ink);
  disc(ctx, cx + s * 0.12, s * 0.48, s * 0.06, ink);
  ctx.strokeStyle = col; // legs
  ctx.lineWidth = Math.max(1, s * 0.05);
  for (const ox of [-0.16, 0, 0.16]) {
    ctx.beginPath();
    ctx.moveTo(cx + ox * s, s * 0.7);
    ctx.lineTo(cx + ox * s, s * 0.84);
    ctx.stroke();
  }
  return canvas;
}

/** Squid / octopus alien — domed head, four tentacle pairs, round eyes. Use for shoot-em-up invader enemies. */
export function squidAlien(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#b06bff';
  const ink = opts.detail ?? '#2a1448';
  const eye = opts.accent ?? '#ffffff';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col; // domed head
  ctx.beginPath();
  ctx.arc(cx, s * 0.46, s * 0.3, Math.PI, 0);
  ctx.fill();
  ctx.fillRect(cx - s * 0.3, s * 0.46, s * 0.6, s * 0.1);
  ctx.fillStyle = col; // tentacles
  for (const ox of [-0.22, -0.07, 0.07, 0.22]) {
    disc(ctx, cx + ox * s, s * 0.62, s * 0.07, col);
    disc(ctx, cx + ox * s, s * 0.72, s * 0.05, col);
  }
  disc(ctx, cx - s * 0.1, s * 0.42, s * 0.07, eye); // eyes
  disc(ctx, cx + s * 0.1, s * 0.42, s * 0.07, eye);
  disc(ctx, cx - s * 0.1, s * 0.42, s * 0.035, ink);
  disc(ctx, cx + s * 0.1, s * 0.42, s * 0.035, ink);
  return canvas;
}

/** Enemy interceptor fighter pointing down — swept wings, narrow fuselage, red cockpit. Use for shoot-em-up diving enemy ships. */
export function interceptor(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#aeb6c2';
  const dark = opts.detail ?? '#5a6470';
  const cockpit = opts.accent ?? '#ff4040';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col; // swept wings
  poly(ctx, [[cx, s * 0.4], [s * 0.1, s * 0.28], [s * 0.32, s * 0.5], [s * 0.68, s * 0.5], [s * 0.9, s * 0.28]]);
  ctx.fill();
  ctx.fillStyle = dark; // fuselage pointing down
  poly(ctx, [[cx - s * 0.12, s * 0.22], [cx + s * 0.12, s * 0.22], [cx, s * 0.86]]);
  ctx.fill();
  disc(ctx, cx, s * 0.34, s * 0.06, cockpit); // cockpit eye
  return canvas;
}

/** Bulky enemy bomber — wide oval hull with engine pods and glowing exhausts. Use for heavy shoot-em-up enemies. */
export function bomber(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#6a7a6a';
  const dark = opts.detail ?? '#3f4a3f';
  const light = opts.accent ?? '#ff6a3a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col; // wide hull
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.5, s * 0.42, s * 0.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = dark; // engine pods
  ctx.fillRect(s * 0.1, s * 0.5, s * 0.14, s * 0.22);
  ctx.fillRect(s * 0.76, s * 0.5, s * 0.14, s * 0.22);
  disc(ctx, cx, s * 0.5, s * 0.1, dark); // cockpit
  disc(ctx, s * 0.17, s * 0.72, s * 0.04, light); // engine glow
  disc(ctx, s * 0.83, s * 0.72, s * 0.04, light);
  return canvas;
}

/** Spiky space mine — eight spike protrusions around a dark body with a red blink light. Use for hazard / obstacle sprites in space games. */
export function mine(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#4a4f57';
  const spike = opts.detail ?? '#2c3036';
  const light = opts.accent ?? '#ff3030';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  ctx.strokeStyle = spike; // spikes
  ctx.lineWidth = Math.max(1, s * 0.06);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * s * 0.2, cy + Math.sin(a) * s * 0.2);
    ctx.lineTo(cx + Math.cos(a) * s * 0.42, cy + Math.sin(a) * s * 0.42);
    ctx.stroke();
  }
  disc(ctx, cx, cy, s * 0.24, col); // body
  disc(ctx, cx - s * 0.06, cy - s * 0.06, s * 0.05, light); // blinking light
  return canvas;
}

