/** Six-petal flower on a stem with a leaf. Use for garden, meadow, or pickup-collectible decoration. */
export function flower(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const petal = opts.color ?? '#ff6ad5';
  const centre = opts.accent ?? '#ffd23f';
  const leaf = opts.detail ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.strokeStyle = leaf; // stem
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.96);
  ctx.lineTo(cx, s * 0.46);
  ctx.stroke();
  ctx.fillStyle = leaf;
  ctx.beginPath();
  ctx.ellipse(cx - s * 0.14, s * 0.66, s * 0.1, s * 0.05, 0.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = petal; // petals
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    disc(ctx, cx + Math.cos(a) * s * 0.15, s * 0.34 + Math.sin(a) * s * 0.15, s * 0.09, petal);
  }
  disc(ctx, cx, s * 0.34, s * 0.09, centre);
  return canvas;
}

/** Tulip flower on a stem with a side leaf — cup of three petals. Use for spring / garden scenery. */
export function tulip(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#e23d4c';
  const leaf = opts.detail ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.strokeStyle = leaf;
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.96);
  ctx.lineTo(cx, s * 0.46);
  ctx.stroke();
  ctx.fillStyle = leaf;
  ctx.beginPath();
  ctx.ellipse(cx + s * 0.12, s * 0.7, s * 0.1, s * 0.05, -0.5, 0, Math.PI * 2);
  ctx.fill();
  // cup of three petals
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(s * 0.3, s * 0.46);
  ctx.quadraticCurveTo(s * 0.3, s * 0.2, cx, s * 0.24);
  ctx.quadraticCurveTo(s * 0.7, s * 0.2, s * 0.7, s * 0.46);
  ctx.quadraticCurveTo(cx, s * 0.36, s * 0.3, s * 0.46);
  ctx.fill();
  ctx.fillRect(cx - s * 0.06, s * 0.22, s * 0.12, s * 0.18); // middle petal
  return canvas;
}

/** Sunflower — 10 yellow petals around a dark brown seed head, on a stem. Use for field / garden scenery or collectibles. */
export function sunflower(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const petal = opts.color ?? '#ffc83a';
  const centre = opts.detail ?? '#7a4a22';
  const leaf = opts.accent ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.strokeStyle = leaf;
  ctx.lineWidth = Math.max(1, s * 0.06);
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.98);
  ctx.lineTo(cx, s * 0.5);
  ctx.stroke();
  ctx.fillStyle = petal; // petals as a ring of triangles
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const px = cx + Math.cos(a) * s * 0.22;
    const py = s * 0.38 + Math.sin(a) * s * 0.22;
    disc(ctx, px, py, s * 0.07, petal);
  }
  disc(ctx, cx, s * 0.38, s * 0.16, centre); // seed head
  return canvas;
}

/** Red mushroom with white spots and a pale stem. Use for forest scenery, Mario-style powerup or hazard sprites. */
export function mushroom(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const cap = opts.color ?? '#e23d2c';
  const spot = opts.accent ?? '#ffffff';
  const stem = opts.detail ?? '#efe6cf';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = stem; // stem
  ctx.fillRect(cx - s * 0.12, s * 0.5, s * 0.24, s * 0.34);
  ctx.fillStyle = cap; // cap (dome)
  ctx.beginPath();
  ctx.arc(cx, s * 0.5, s * 0.32, Math.PI, 0);
  ctx.fill();
  ctx.fillStyle = spot; // spots
  disc(ctx, cx - s * 0.12, s * 0.38, s * 0.05, spot);
  disc(ctx, cx + s * 0.14, s * 0.42, s * 0.04, spot);
  disc(ctx, cx + s * 0.02, s * 0.3, s * 0.04, spot);
  return canvas;
}

/** Green cactus — round-capped body with two upward arms and spine flecks. Use for desert / western scenery or obstacles. */
export function cactus(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#3fae5a';
  const dark = opts.detail ?? '#2a7a3e';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  // round-capped body + arms via thick strokes
  ctx.strokeStyle = col;
  ctx.lineWidth = s * 0.22;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.92);
  ctx.lineTo(cx, s * 0.28);
  ctx.stroke();
  ctx.lineWidth = s * 0.14;
  ctx.beginPath(); // left arm
  ctx.moveTo(cx - s * 0.02, s * 0.62);
  ctx.lineTo(s * 0.22, s * 0.62);
  ctx.lineTo(s * 0.22, s * 0.46);
  ctx.moveTo(cx + s * 0.02, s * 0.54); // right arm
  ctx.lineTo(s * 0.78, s * 0.54);
  ctx.lineTo(s * 0.78, s * 0.4);
  ctx.stroke();
  ctx.strokeStyle = dark; // spine flecks
  ctx.lineWidth = 1;
  for (let y = 0.34; y < 0.88; y += 0.12) ctx.strokeRect(cx, s * y, 0.5, 1);
  return canvas;
}

/** Rounded bush — four overlapping green circles with a sheen highlight and shadow base. Use for outdoor scenery, platformer decoration. */
export function bush(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#3a8f3a';
  const dark = opts.detail ?? '#256025';
  const light = opts.accent ?? '#5bbf4f';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  for (const [ox, oy, r] of [[-0.22, 0.06, 0.2], [0.22, 0.06, 0.2], [0, -0.06, 0.24], [0, 0.14, 0.22]]) {
    disc(ctx, cx + ox * s, s * 0.58 + oy * s, r * s, col);
  }
  disc(ctx, cx - s * 0.1, s * 0.42, s * 0.08, light); // sheen
  ctx.fillStyle = dark;
  ctx.fillRect(s * 0.2, s * 0.78, s * 0.6, s * 0.06); // shadow base
  return canvas;
}

/** Pine / fir tree — three stacked triangular tiers over a brown trunk. Use for forest, mountain, or Christmas scenery. */
export function pineTree(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#2f7d3a';
  const trunk = opts.detail ?? '#7a4a22';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = trunk;
  ctx.fillRect(cx - s * 0.05, s * 0.78, s * 0.1, s * 0.16);
  ctx.fillStyle = col; // stacked tiers
  for (const [ty, w] of [[0.16, 0.18], [0.4, 0.26], [0.6, 0.34]]) {
    poly(ctx, [[cx, s * ty], [cx - w * s, s * (ty + 0.26)], [cx + w * s, s * (ty + 0.26)]]);
    ctx.fill();
  }
  return canvas;
}

/** Grey rock / boulder — irregular polygon with a light top facet. Use for outdoor obstacles, cave scenery, breakable blocks. */
export function rock(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#8a8f98';
  const light = opts.accent ?? '#abb0b8';
  const dark = opts.detail ?? '#5f636b';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  poly(ctx, [[s * 0.14, s * 0.78], [s * 0.24, s * 0.46], [s * 0.46, s * 0.36], [s * 0.72, s * 0.42], [s * 0.86, s * 0.66], [s * 0.8, s * 0.8]]);
  ctx.fillStyle = col;
  ctx.fill();
  ctx.fillStyle = light; // top facet
  poly(ctx, [[s * 0.24, s * 0.46], [s * 0.46, s * 0.36], [s * 0.6, s * 0.46], [s * 0.4, s * 0.52]]);
  ctx.fill();
  ctx.fillStyle = dark;
  ctx.fillRect(s * 0.18, s * 0.78, s * 0.62, s * 0.04);
  return canvas;
}

