// Characters — assorted
// ---------------------------------------------------------------------------

/** Wizard — pointed hat with a star, long beard, and eyes. Use for mage NPC, player class sprite. */
export function wizard(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const hat = opts.color ?? '#5b3fb0';
  const skin = opts.detail ?? '#f0c8a0';
  const beard = opts.accent ?? '#e8eef5';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s * 0.5, s * 0.18, skin); // face
  // beard
  ctx.fillStyle = beard;
  poly(ctx, [[cx - s * 0.16, s * 0.5], [cx + s * 0.16, s * 0.5], [cx, s * 0.92]]);
  ctx.fill();
  // hat (cone + brim + star)
  ctx.fillStyle = hat;
  poly(ctx, [[cx, s * 0.06], [cx - s * 0.22, s * 0.44], [cx + s * 0.22, s * 0.44]]);
  ctx.fill();
  ctx.fillRect(cx - s * 0.28, s * 0.42, s * 0.56, s * 0.06); // brim
  ctx.fillStyle = '#ffd23f';
  poly(ctx, starPoints(cx, s * 0.28, s * 0.07, s * 0.03, 5));
  ctx.fill();
  ctx.fillStyle = '#222'; // eyes
  ctx.fillRect(Math.round(cx - s * 0.08), Math.round(s * 0.5), 1, 2);
  ctx.fillRect(Math.round(cx + s * 0.06), Math.round(s * 0.5), 1, 2);
  return canvas;
}

/** Bat — dark body with pointed ears, scalloped wings, and glowing eyes. Use for cave enemies, Halloween-themed sprites. */
export function bat(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#4a3f6b';
  const eye = opts.accent ?? '#ffd23f';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col;
  disc(ctx, cx, s * 0.52, s * 0.18, col); // body
  // ears
  poly(ctx, [[cx - s * 0.12, s * 0.4], [cx - s * 0.04, s * 0.26], [cx - s * 0.02, s * 0.42]]);
  poly(ctx, [[cx + s * 0.12, s * 0.4], [cx + s * 0.04, s * 0.26], [cx + s * 0.02, s * 0.42]]);
  ctx.fill();
  // scalloped wings
  ctx.beginPath();
  ctx.moveTo(cx - s * 0.12, s * 0.48);
  ctx.quadraticCurveTo(cx - s * 0.34, s * 0.36, cx - s * 0.46, s * 0.5);
  ctx.quadraticCurveTo(cx - s * 0.34, s * 0.5, cx - s * 0.3, s * 0.6);
  ctx.quadraticCurveTo(cx - s * 0.22, s * 0.54, cx - s * 0.12, s * 0.6);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(cx + s * 0.12, s * 0.48);
  ctx.quadraticCurveTo(cx + s * 0.34, s * 0.36, cx + s * 0.46, s * 0.5);
  ctx.quadraticCurveTo(cx + s * 0.34, s * 0.5, cx + s * 0.3, s * 0.6);
  ctx.quadraticCurveTo(cx + s * 0.22, s * 0.54, cx + s * 0.12, s * 0.6);
  ctx.fill();
  disc(ctx, cx - s * 0.07, s * 0.5, s * 0.035, eye); // eyes
  disc(ctx, cx + s * 0.07, s * 0.5, s * 0.035, eye);
  return canvas;
}

/** Floating eyeball — sclera with vein lines, iris, pupil, and glint. Use for horror enemy, floating eye monster. */
export function eyeball(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const iris = opts.color ?? '#3a8fe0';
  const white = opts.detail ?? '#f4f6fb';
  const vein = opts.accent ?? '#e06a6a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  const cy = s / 2;
  disc(ctx, cx, cy, s * 0.38, white); // sclera
  ctx.strokeStyle = vein; // veins
  ctx.lineWidth = 1;
  for (const a of [2.4, 3.4, 4.3]) {
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * s * 0.36, cy + Math.sin(a) * s * 0.36);
    ctx.lineTo(cx + Math.cos(a) * s * 0.16, cy + Math.sin(a) * s * 0.16);
    ctx.stroke();
  }
  disc(ctx, cx, cy, s * 0.18, iris); // iris
  disc(ctx, cx, cy, s * 0.09, '#1a1a1a'); // pupil
  disc(ctx, cx - s * 0.06, cy - s * 0.06, s * 0.04, '#ffffff'); // glint
  return canvas;
}

/** Human nose with nostrils and a tip shade. Use for face-builder UIs, character customisation. */
export function nose(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const skin = opts.color ?? '#f0b890';
  const shade = opts.detail ?? '#d49770';
  const dark = opts.accent ?? '#7a4a30';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = skin;
  ctx.beginPath();
  ctx.moveTo(cx, s * 0.18);
  ctx.quadraticCurveTo(cx - s * 0.1, s * 0.5, cx - s * 0.26, s * 0.7);
  ctx.quadraticCurveTo(cx - s * 0.18, s * 0.84, cx, s * 0.78); // left nostril wing
  ctx.quadraticCurveTo(cx + s * 0.18, s * 0.84, cx + s * 0.26, s * 0.7);
  ctx.quadraticCurveTo(cx + s * 0.1, s * 0.5, cx, s * 0.18);
  ctx.fill();
  ctx.fillStyle = shade; // tip shade
  disc(ctx, cx, s * 0.66, s * 0.12, shade);
  ctx.fillStyle = dark; // nostrils
  disc(ctx, cx - s * 0.1, s * 0.72, s * 0.04, dark);
  disc(ctx, cx + s * 0.1, s * 0.72, s * 0.04, dark);
  return canvas;
}

/** Green frog — oval body, bulging eye bumps, wide grin. Use for swamp / pond enemy or animal sprites. */
export function frog(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#5fb83a';
  const dark = opts.detail ?? '#3a7a24';
  const eye = opts.accent ?? '#ffffff';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  ctx.fillStyle = col; // body
  ctx.beginPath();
  ctx.ellipse(cx, s * 0.6, s * 0.34, s * 0.26, 0, 0, Math.PI * 2);
  ctx.fill();
  disc(ctx, cx - s * 0.16, s * 0.36, s * 0.12, col); // eye bumps
  disc(ctx, cx + s * 0.16, s * 0.36, s * 0.12, col);
  disc(ctx, cx - s * 0.16, s * 0.34, s * 0.07, eye);
  disc(ctx, cx + s * 0.16, s * 0.34, s * 0.07, eye);
  disc(ctx, cx - s * 0.16, s * 0.35, s * 0.035, '#1a1a1a');
  disc(ctx, cx + s * 0.16, s * 0.35, s * 0.035, '#1a1a1a');
  ctx.strokeStyle = dark; // mouth
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.arc(cx, s * 0.58, s * 0.2, 0.2, Math.PI - 0.2);
  ctx.stroke();
  return canvas;
}

/** Carved Halloween pumpkin — orange body with rib arcs, green stem, and triangle eyes + jagged mouth. Use for Halloween themes, seasonal decoration. */
export function pumpkin(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const col = opts.color ?? '#ff8c1a';
  const rib = opts.detail ?? '#d96e0e';
  const stem = opts.accent ?? '#3fae4a';
  const { canvas, ctx } = makeCanvas(s, s);
  const cx = s / 2;
  disc(ctx, cx, s * 0.56, s * 0.36, col); // body
  ctx.strokeStyle = rib; // ribs
  ctx.lineWidth = Math.max(1, s * 0.05);
  for (const ox of [-0.18, 0, 0.18]) {
    ctx.beginPath();
    ctx.moveTo(cx + ox * s, s * 0.24);
    ctx.quadraticCurveTo(cx + ox * s * 1.5, s * 0.56, cx + ox * s, s * 0.88);
    ctx.stroke();
  }
  ctx.fillStyle = stem; // stem
  ctx.fillRect(cx - s * 0.04, s * 0.18, s * 0.08, s * 0.1);
  ctx.fillStyle = '#2a1a08'; // carved face
  poly(ctx, [[cx - s * 0.2, s * 0.48], [cx - s * 0.08, s * 0.48], [cx - s * 0.14, s * 0.58]]);
  ctx.fill();
  poly(ctx, [[cx + s * 0.2, s * 0.48], [cx + s * 0.08, s * 0.48], [cx + s * 0.14, s * 0.58]]);
  ctx.fill();
  poly(ctx, [[cx - s * 0.2, s * 0.66], [cx - s * 0.1, s * 0.72], [cx, s * 0.66], [cx + s * 0.1, s * 0.72], [cx + s * 0.2, s * 0.66], [cx, s * 0.78]]);
  ctx.fill();
  return canvas;
}

/** Snail — coiled shell with swirl arcs, green body / foot, eye stalks. Use for garden / slow enemy sprites. */
export function snail(opts: SpriteOptions = {}): HTMLCanvasElement {
  const s = opts.size ?? 16;
  const shell = opts.color ?? '#e0a85a';
  const body = opts.detail ?? '#b6e08a';
  const swirl = opts.accent ?? '#a8742e';
  const { canvas, ctx } = makeCanvas(s, s);
  // body (foot) + head
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(s * 0.1, s * 0.8);
  ctx.quadraticCurveTo(s * 0.1, s * 0.64, s * 0.4, s * 0.64);
  ctx.lineTo(s * 0.86, s * 0.64);
  ctx.quadraticCurveTo(s * 0.94, s * 0.7, s * 0.86, s * 0.8);
  ctx.closePath();
  ctx.fill();
  disc(ctx, s * 0.82, s * 0.56, s * 0.1, body); // head
  // eye stalks
  ctx.strokeStyle = body;
  ctx.lineWidth = Math.max(1, s * 0.04);
  ctx.beginPath();
  ctx.moveTo(s * 0.84, s * 0.5);
  ctx.lineTo(s * 0.9, s * 0.38);
  ctx.moveTo(s * 0.78, s * 0.5);
  ctx.lineTo(s * 0.74, s * 0.38);
  ctx.stroke();
  disc(ctx, s * 0.9, s * 0.36, s * 0.03, '#1a1a1a');
  disc(ctx, s * 0.74, s * 0.36, s * 0.03, '#1a1a1a');
  // shell
  disc(ctx, s * 0.42, s * 0.46, s * 0.26, shell);
  ctx.strokeStyle = swirl;
  ctx.lineWidth = Math.max(1, s * 0.05);
  ctx.beginPath();
  ctx.arc(s * 0.42, s * 0.46, s * 0.16, 0, Math.PI * 1.8);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(s * 0.42, s * 0.46, s * 0.08, 0, Math.PI * 1.6);
  ctx.stroke();
  return canvas;
}
